import { lunarGeometry } from './diagrams.js';
import { bodies,planets,byId,children,regions,AU,DAY,C,DATA_DATE,MIN_DATE,MAX_DATE,SOURCES } from './data.js';
import { daylight,lunarPhase,orbitExperiment,gravity,distanceAt,angularSeparation,apparentDiameter,positionsAt,orbitPoint,TAU,RAD,length,sub,clamp } from './model.js';
import { tours,activities,glossary,missions } from './content.js';
import { e,icon,button as B,iconButton as IB,select as S,range as R,number as N,check as K,section,notice,external } from './ui.js';

export const toolNames={tools:['Seu próximo ponto de descoberta','Your next discovery'],learn:['A curiosidade leva você mais longe','Curiosity takes you further'],compare:['Mundos lado a lado','Worlds side by side'],measure:['A distância entre mundos','The distance between worlds'],scale:['Laboratório de escala','Scale laboratory'],seasons:['O que cria as estações?','What creates the seasons?'],moon:['Luz, fases e eclipses','Light, phases and eclipses'],kepler:['A dança das órbitas','The dance of orbits'],gravity:['Massa e peso','Mass and weight'],outer:['Além de Netuno','Beyond Neptune'],missions:['Uma história de descobertas','A history of discovery'],glossary:['Enciclopédia do observatório','Observatory encyclopedia'],article:['Uma ideia, outra perspectiva','One idea, another perspective'],collections:['Seu caderno de observação','Your observation journal'],settings:['Faça deste espaço o seu','Make this space your own'],help:['Um guia para explorar','A guide to exploring'],time:['Viaje no tempo','Travel through time'],frames:['Uma mudança de perspectiva','A change of perspective'],capture:['Sua fotografia','Your photograph'],import:['Revisar importação','Review import'],share:['Leve esta vista com você','Take this view with you'],catalog:['Todos os mundos','All the worlds'],commands:['O que você quer explorar?','What would you like to explore?']};
toolNames.camera=['Câmera e perspectiva','Camera and perspective'];
const optionBodies=(name,list=bodies)=>list.map(b=>[b.id,name(b)]);
const readout=(value,label)=>`<div class="readout"><strong>${value}</strong><small>${label}</small></div>`;
const texture=b=>b.texture?`url('/assets/${b.texture}.jpg')`:'none';
const svg=(content,label,viewBox='0 0 620 350')=>`<svg viewBox="${viewBox}" role="img" aria-label="${e(label)}">${content}</svg>`;
const card=(key,title,desc,ico,extra='')=>B('open',`<div><h3>${title}</h3><p>${desc}</p>${extra}</div>`,{ico,value:key,cls:'tool-card'});

export function renderTool(ctx){const {s,L,name,fmt,scene}=ctx,t=s.tool,d=s.toolData;const bt=(id,title,ico)=>B('open',title,{value:id,ico,cls:'secondary'});
  if(t==='camera')return `<div class="tool-grid">${[['overview',L('Sistema completo','Whole system'),'reset'],['top',L('Eclíptica vista de cima','Top-down ecliptic'),'compass'],['low',L('Perspectiva baixa','Low perspective'),'orbit'],['equator',L('Equador do alvo','Target equator'),'saturn'],['polar',L('Polo do alvo','Target pole'),'earth']].map(([value,label,ico])=>B('camera-preset',label,{value,ico,cls:'tool-card'})).join('')}${B('free',L('Câmera livre','Free camera'),{ico:'focus',cls:'tool-card'})}</div><div class="row" style="margin-top:22px">${IB('camera-pan',L('Deslocar para a esquerda','Pan left'),'back',{value:'-1,0',cls:'secondary'})}${IB('camera-pan',L('Deslocar para a direita','Pan right'),'next',{value:'1,0',cls:'secondary'})}${B('camera-pan',L('Subir','Pan up'),{value:'0,1',cls:'secondary'})}${B('camera-pan',L('Descer','Pan down'),{value:'0,-1',cls:'secondary'})}${B('view-history',L('Vista anterior','Previous view'),{value:'-1',ico:'back',cls:'secondary'})}${B('view-history',L('Vista seguinte','Next view'),{value:'1',ico:'next',cls:'secondary'})}${B('photo',L('Fotografar','Photograph'),{ico:'camera',cls:'secondary'})}${B('settings',L('Preferências','Preferences'),{ico:'settings',cls:'secondary'})}${B('zen',L('Sem distrações','Distraction-free'),{ico:'eye',cls:'secondary'})}${B('share',L('Compartilhar configuração da vista','Share view configuration'),{ico:'share',cls:'primary'})}</div>${notice(L('Arrastar interrompe viagens automáticas, mas preserva o acompanhamento do alvo. Para se separar dele, escolha Câmera livre.','Dragging interrupts automatic travel but keeps tracking the target. Choose Free camera to detach.'))}`;
  if(t==='tools')return `<p class="lead">${L('Observe uma relação. Mude uma variável. Encontre uma nova pergunta.','Observe a relationship. Change a variable. Find a new question.')}</p><div class="tool-grid">${[
    ['compare',L('Comparar mundos','Compare worlds'),L('Tamanhos reais. Perspectivas inesperadas.','True sizes. Unexpected perspectives.'),'compare'],
    ['measure',L('Medir distâncias','Measure distances'),L('Uma régua e uma viagem à velocidade da luz.','A ruler and a journey at the speed of light.'),'ruler'],
    ['scale',L('Entender a escala','Understand scale'),L('E se a Terra coubesse na sua mão?','What if Earth fit in your hand?'),'orbit'],
    ['seasons',L('Estações e luz','Seasons and light'),L('Mude a inclinação. Descubra o que acontece.','Change the tilt. Discover what happens.'),'earth'],
    ['moon',L('Fases e eclipses','Phases and eclipses'),L('Veja a Lua de duas perspectivas.','See the Moon from two perspectives.'),'moon'],
    ['kepler',L('Criar uma órbita','Create an orbit'),L('Um experimento com as leis de Kepler.','An experiment with Kepler’s laws.'),'tools'],
    ['gravity',L('Investigar a gravidade','Investigate gravity'),L('Mesma massa, pesos diferentes.','Same mass, different weights.'),'compass'],
    ['frames',L('Trocar o referencial','Change reference frame'),L('O movimento depende de onde observamos.','Motion depends on where we observe.'),'focus'],
    ['outer',L('Além de Netuno','Beyond Neptune'),L('Nossa vizinhança é maior do que parece.','Our neighborhood is larger than it seems.'),'spark']
  ].map(x=>card(...x)).join('')}</div><div class="row" style="margin-top:22px">${B('photo',L('Fotografar a cena','Photograph the scene'),{ico:'camera',cls:'secondary'})}${bt('collections',L('Abrir meu caderno','Open my journal'),'book')}${bt('time',L('Calendário e tempo','Calendar and time'),'calendar')}</div>`;
  if(t==='learn')return `<div class="row between"><p>${L('Não é preciso saber por onde começar. Escolha uma viagem.','You do not need to know where to begin. Choose a journey.')}</p><span class="progress-count">${s.data.progress.activities.length} / 12 ${L('atividades','activities')}</span></div><div class="tool-grid">${tours.map(tr=>B('start-tour',`<div><h3>${L(...tr.title)}</h3><p>${L(...tr.subtitle)}</p><div class="eyebrow">${tr.stops.length} ${L('paradas','stops')} · ${s.data.progress.tours.includes(tr.id)?L('Concluída','Completed'):L('No seu ritmo','At your pace')}</div></div>`,{value:tr.id,ico:tr.icon,cls:'tool-card'})).join('')}</div>${section(L('Aprenda fazendo','Learn by doing'),`<div class="glossary-grid">${activities.map((a,i)=>B('start-activity',`<span class="eyebrow">${String(i+1).padStart(2,'0')} / ${L(...a.theme)}</span><h3>${s.data.progress.activities.includes(a.id)?'✓ ':''}${L(...a.title)}</h3>`,{value:a.id,cls:'glossary-item'})).join('')}</div>`)}<div class="row">${bt('glossary',L('Explorar conceitos','Explore concepts'),'book')}${bt('missions',L('História da exploração','Exploration history'),'spark')}${B('activity-sequence',L('Continuar sequência de atividades','Continue activity sequence'),{ico:'next',cls:'secondary'})}</div>`;
  if(t==='compare')return renderCompare(ctx);
  if(t==='scale')return renderScale(ctx);
  if(t==='measure')return renderMeasure(ctx);
  if(t==='seasons')return renderSeasons(ctx);
  if(t==='moon')return renderMoon(ctx);
  if(t==='kepler')return renderKepler(ctx);
  if(t==='gravity'){const b=byId[d.gravityBody],g=gravity(b.mass,b.radius),mass=d.personMass;return `<div class="lab-layout"><div><div class="diagram">${svg(`<circle cx="310" cy="172" r="100" fill="${b.color}" opacity=".7"/><path d="M310 35v75m-9-13 9 13 9-13" stroke="#e5ba7b" stroke-width="3" fill="none"/><text x="310" y="174" text-anchor="middle" style="font-size:30px;fill:#fff">${fmt(g,2)} m/s²</text><text x="310" y="201" text-anchor="middle">${name(b)}</text>`,L('Aceleração gravitacional no raio médio','Gravitational acceleration at the mean radius'))}</div><div class="lab-readout">${readout(`${fmt(mass)} kg`,L('Sua massa','Your mass'))}${readout(`${fmt(mass*g,1)} N`,L('Seu peso calculado','Your calculated weight'))}${readout(`${fmt(g/gravity(byId.earth.mass,byId.earth.radius),3)}×`,L('Gravidade da Terra','Earth gravity'))}</div></div><div class="stack">${S('gravityBody',L('Corpo de referência','Reference body'),optionBodies(name,bodies.filter(b=>b.mass)),d.gravityBody)}${N('personMass',L('Massa do objeto (kg)','Object mass (kg)'),mass,1,10000)}${notice(L('g = GM/r² · W = mg. Modelo esférico no raio médio; omite rotação, relevo e atmosfera. Gigantes não possuem uma superfície sólida nesse raio.','g = GM/r² · W = mg. Spherical model at mean radius; omits rotation, terrain and atmosphere. Giants have no solid surface at this radius.'))}${B('lab-reset',L('Restaurar laboratório','Reset laboratory'),{cls:'secondary',ico:'reset'})}</div></div>`;}
  if(t==='time')return renderTime(ctx);
  if(t==='settings')return renderSettings(ctx);
  if(t==='collections')return renderCollections(ctx);
  if(t==='glossary'){const q=(d.glossaryQuery||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const list=glossary.filter(a=>[...a.title,a.id,...a.definition].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));return `<input class="search-wide" type="search" data-field="glossaryQuery" value="${e(d.glossaryQuery||'')}" placeholder="${L('Buscar uma ideia…','Search for an idea…')}" aria-label="${L('Buscar na enciclopédia','Search encyclopedia')}"/><div class="glossary-grid">${list.map(a=>B('article',`<h3>${L(...a.title)}</h3><p>${L(...a.definition)}</p>`,{value:a.id,cls:'glossary-item'})).join('')||`<div class="empty">${L('Nenhum conceito encontrado. Tente outra palavra.','No concepts found. Try another word.')}</div>`}</div>`;}
  if(t==='article'){const a=glossary.find(a=>a.id===d.article)||glossary[0];return `<article class="article"><div class="eyebrow">${L('ENCICLOPÉDIA','ENCYCLOPEDIA')}</div><h2 style="margin-top:12px">${L(...a.title)}</h2><p class="lead">${L(...a.definition)}</p><details open><summary>${L('Um pouco mais a fundo','A little deeper')}</summary><p>${L(...a.detail)}</p></details><div class="row">${bt(a.tool,L('Explorar este conceito','Explore this concept'),'arrow')}${B('tool-back',L('Voltar à leitura anterior','Back to previous reading'),{ico:'back',cls:'secondary'})}</div><div class="divider"></div><p class="small">${L('Referências do modelo','Model references')} · ${DATA_DATE}</p><div class="source-list">${Object.values(SOURCES).filter((_,i)=>i<5).map(([title,url])=>external(url,title)).join('')}</div></article>`;}
  if(t==='missions')return renderMissions(ctx);
  if(t==='outer')return renderOuter(ctx);
  if(t==='frames')return renderFrames(ctx);
  if(t==='help')return `<div class="lab-layout"><div>${section(L('A cena é sua','The scene is yours'),`<p>${L('Arraste com um dedo ou o botão esquerdo para orbitar. Use dois dedos ou a roda para aproximar. Arraste com o botão direito para deslocar. Um toque seleciona; Focalizar aproxima.','Drag with one finger or the left button to orbit. Use two fingers or the wheel to zoom. Right-drag to pan. One tap selects; Focus brings you closer.')}</p><p>${L('A câmera acompanha o alvo após focalizar. Você pode girar sem perder o acompanhamento. A ação Câmera livre desliga esse vínculo.','The camera tracks the target after focusing. You can orbit without losing tracking. Free camera releases that link.')}</p><div class="row">${B('reset-view',L('Visão geral','Overview'),{ico:'reset',cls:'secondary'})}${B('free',L('Câmera livre','Free camera'),{ico:'compass',cls:'secondary'})}${B('restart-tutorial',L('Recomeçar as dicas','Restart hints'),{ico:'help',cls:'secondary'})}</div>`)}${section(L('Câmera pelo teclado','Keyboard camera'),`<p>${L('Dê foco à cena com Tab. Setas giram a câmera; + e − aproximam e afastam. Os botões de câmera também oferecem deslocamento. Tab sai da cena normalmente.','Focus the scene using Tab. Arrow keys orbit the camera; + and − zoom. Camera buttons also provide pan. Tab leaves the scene normally.')}</p>${notice(L('Preferência por movimento reduzido é respeitada. A simulação pode ser pausada a qualquer momento.','Reduced-motion preference is respected. The simulation can be paused at any time.'))}`)}</div><div class="table-wrap"><table><thead><tr><th>${L('Tecla','Key')}</th><th>${L('Ação','Action')}</th></tr></thead><tbody>${[['Space',L('Reproduzir / pausar','Play / pause')],['R',L('Restaurar vista','Reset view')],['O',L('Alternar órbitas','Toggle orbits')],['L',L('Alternar rótulos','Toggle labels')],['/',L('Buscar ou executar comando','Search or run command')],['F',L('Focalizar seleção','Focus selection')],['G',L('Acompanhar seleção','Follow selection')],['C',L('Comparar','Compare')],['P',L('Fotografia','Photography')],['H',L('Ocultar interface','Hide interface')],['Escape',L('Fechar camada mais recente','Close most recent layer')]].map(([k,v])=>`<tr><td><kbd>${k}</kbd></td><td>${v}</td></tr>`).join('')}</tbody></table></div></div>`;
  if(t==='capture')return `<img class="photo-preview" src="${s.capture.url}" alt="${L('Fotografia exportada do observatório','Exported observatory photograph')}"/><div class="row">${external(s.capture.url,L('Abrir imagem completa','Open full image'))}<a class="download-link" href="${s.capture.url}" download="observatory-${new Date(s.clock.time).toISOString().slice(0,10)}.png">${L('Baixar PNG','Download PNG')} · ${s.capture.width} × ${s.capture.height}</a></div>${notice(L('Imagem gerada neste navegador. Os rótulos e créditos escolhidos estão incorporados ao PNG.','Image generated in this browser. Selected labels and credits are embedded in the PNG.'))}`;
  if(t==='import')return `<p>${L('O arquivo foi validado. Confira antes de alterar suas coleções.','The file has been validated. Review it before changing your collections.')}</p>${s.importData?.kind==='observatory-scene'?notice(L('Arquivo de cena: somente alvo, câmera, data e escala.','Scene file: only target, camera, date and scale.')):`<div class="lab-readout">${['viewpoints','bookmarks','notes'].map(k=>readout(s.importData?.[k]?.length||0,L(...({viewpoints:['Vistas','Viewpoints'],bookmarks:['Datas','Bookmarks'],notes:['Anotações','Notes']}[k])))).join('')}</div>`}<div class="row" style="margin-top:22px">${B('import-confirm',L('Mesclar conteúdo validado','Merge validated content'),{cls:'primary',ico:'check'})}${B('import-cancel',L('Cancelar importação','Cancel import'),{cls:'secondary'})}</div>`;
  if(t==='share')return `<p>${L('Esta prévia é local. Exporte uma configuração portátil para abrir nesta aplicação. Ela não contém suas anotações pessoais.','This preview is local. Export a portable configuration to open in this application. It contains no private journal notes.')}</p><textarea class="search-wide" readonly aria-label="${L('Configuração pública da cena','Public scene configuration')}">${e(JSON.stringify(s.shareData,null,2))}</textarea><div class="row">${B('export-scene',L('Baixar cena JSON','Download scene JSON'),{ico:'download',cls:'primary'})}${B('copy-scene',L('Copiar configuração','Copy configuration'),{ico:'share',cls:'secondary'})}</div>`;
  if(t==='catalog'||t==='commands')return ctx.renderCatalog(t==='commands');
  return '';
}

function renderCompare({s,L,name,fmt}){const d=s.toolData.compare,list=d.ids.map(id=>byId[id]),reference=byId[d.ref]||list[0],max=Math.max(...list.map(b=>b.radius)),unit=s.prefs.units,factor=unit==='mi'?.621371:1;
  const fields=[['diameter',L('Diâmetro médio','Mean diameter'),b=>`${fmt(b.radius*2*factor,1)} ${unit}`],['ratio',`${L('Diâmetros de','Diameters of')} ${name(reference)}`,b=>`${fmt(b.radius/reference.radius,4)}×`],['mass',L('Massa (kg)','Mass (kg)'),b=>b.mass?fmt(b.mass):L('Não disponível','Unavailable')],['massRatio',`${L('Massas de','Masses of')} ${name(reference)}`,b=>b.mass&&reference.mass?`${fmt(b.mass/reference.mass,4)}×`:'—'],['gravity',L('Gravidade de referência (m/s²)','Reference gravity (m/s²)'),b=>b.gravity?fmt(b.gravity,2):'—'],['density',L('Densidade (g/cm³)','Density (g/cm³)'),b=>b.density?fmt(b.density,3):'—'],['solarDay',L('Dia solar médio aproximado (dias)','Approximate mean solar day (days)'),b=>b.solarDay?fmt(b.solarDay,3):L('Não se aplica ao modelo','Not applicable to this model')],['rotation',L('Rotação sideral (dias; sinal da fonte)','Sidereal rotation (days; source sign)'),b=>fmt(b.rotation,4)],['orbit',L('Período orbital (dias)','Orbital period (days)'),b=>b.period?`${fmt(b.period,2)} · ${name(byId[b.parent])}`:L('Não se aplica','Not applicable')],['temp',L('Temperatura (K) e contexto','Temperature (K) and context'),b=>b.temperature?`${fmt(b.temperature)} · ${L(...b.temperatureContext)}`:L('Não incluída no conjunto','Not included in this dataset')]];
  return `<div class="compare-chips">${list.map((b,i)=>`<div class="compare-chip"><i class="body-dot" style="--body-color:${b.color}"></i><span>${name(b)}</span>${IB('compare-left',L('Mover para a esquerda','Move left'),'back',{value:b.id,disabled:i===0})}${IB('compare-remove',L('Remover','Remove'),'close',{value:b.id,disabled:list.length<=2})}</div>`).join('')}</div><div class="form-grid">${S('compareAdd',L('Adicionar até quatro mundos','Add up to four worlds'),[['',L('Escolher um corpo…','Choose a body…')],...optionBodies(name,bodies.filter(b=>!d.ids.includes(b.id)))],'',list.length===4?'disabled':'')}${S('compareRef',L('Corpo de referência','Reference body'),optionBodies(name,list),reference.id)}</div><div class="row" style="margin-top:15px">${[['earth,mars',L('Terra / Marte','Earth / Mars')],['earth,venus',L('Terra / Vênus','Earth / Venus')],['jupiter,saturn',L('Júpiter / Saturno','Jupiter / Saturn')],['earth,moon',L('Terra / Lua','Earth / Moon')],['pluto,charon',L('Plutão / Caronte','Pluto / Charon')]].map(([v,txt])=>B('compare-pair',txt,{value:v,cls:'secondary'})).join('')}</div><div class="comparison-stage" style="--count:${list.length}">${list.map(b=>`<div class="comparison-body"><div class="comparison-ball" style="--ratio:${b.radius/max};width:${b.radius/max*150}px;height:${b.radius/max*150}px;--body-color:${b.color};--texture:${texture(b)}"></div><span>${name(b)}</span></div>`).join('')}</div><div class="linear-ruler"><span>${L('DIÂMETROS · ESCALA LINEAR ÚNICA','DIAMETERS · ONE LINEAR SCALE')}</span><span>${fmt(2*max*factor)} ${unit}</span></div><div class="table-wrap comparison-table"><table><thead><tr><th>${L('Grandeza','Quantity')}</th>${list.map(b=>`<th>${name(b)}</th>`).join('')}</tr></thead><tbody>${fields.map(([,title,fn])=>`<tr><td>${title}</td>${list.map(b=>`<td>${fn(b)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="metric-note">${L('Gigantes: gravidade em nível de referência, sem solo sólido. Rotação sideral difere do dia solar. Os períodos das luas são relativos ao planeta, não ao Sol.','Giants: gravity at a reference level, without solid ground. Sidereal rotation differs from solar day. Moon periods are relative to the parent, not the Sun.')}</p>${list.some(b=>b.radiusContext)?notice(list.filter(b=>b.radiusContext).map(b=>name(b)+': '+L(...b.radiusContext)).join(' ')):''}<div class="row">${B('compare-swap',L('Inverter ordem','Reverse order'),{ico:'reverse',cls:'secondary'})}${B('export-comparison',L('Exportar tabela CSV','Export CSV table'),{ico:'download',cls:'primary'})}${B('compare-image',L('Exportar diagrama SVG','Export SVG diagram'),{ico:'camera',cls:'secondary'})}${S('pref.units',L('Unidades de diâmetro','Diameter units'),[['km','km'],['mi',L('Milhas','Miles')]],unit)}</div>`;
}

function renderScale({s,L,name,fmt}){
  const d=s.toolData.scale,ref=byId[d.ref],subset=planets.filter(b=>d.group==='inner'?!b.giant:d.group==='giants'?b.giant:true),list=d.includeSun?[byId.sun,...subset]:subset,diameterM=d.size*(d.unit==='cm'?.01:d.unit==='mm'?.001:1),ratio=diameterM/(ref.radius*2),maxR=Math.max(...list.map(b=>b.radius));let diagram='';
  if(d.view==='sizes'){
    const unit=Math.min(67/maxR,(540-18*(list.length-1))/list.reduce((sum,b)=>sum+2*b.radius,0));let cursor=40;
    diagram=svg(list.map((b,i)=>{const r=b.radius*unit,cx=cursor+r,labelX=45+i*530/Math.max(1,list.length-1);cursor+=2*r+18;return '<circle cx="'+cx+'" cy="'+(180-r)+'" r="'+r+'" fill="'+b.color+'"/><path d="M'+cx+' 185 L'+labelX+' '+(213+i%2*24)+'" stroke="'+b.color+'" opacity=".4"/><text x="'+labelX+'" y="'+(226+i%2*24)+'" text-anchor="middle" style="font-size:10px">'+name(b)+'</text>';}).join('')+'<path d="M40 280h'+maxR*2*unit+'m0-4v8M40 276v8" stroke="#99b5c4"/><text x="40" y="310">'+fmt(maxR*2)+' km · '+L('diâmetros lineares','linear diameters')+'</text>',L('Todos os discos compartilham a mesma escala de diâmetro','All disks share the same diameter scale'));
  }else{
    const max=subset.at(-1).a,log=d.view!=='true'&&d.axis==='log',coord=a=>40+(log?Math.log1p(a/AU)/Math.log1p(max/AU):a/max)*535;
    diagram=svg('<line x1="40" y1="170" x2="585" y2="170" stroke="#7a8f9f"/><circle cx="40" cy="170" r="'+(d.view==='true'?byId.sun.radius/max*535:7)+'" fill="#e5ba7b"/>'+subset.map((b,i)=>{const x=coord(b.a),labelX=65+i*500/Math.max(1,subset.length-1),labelY=i%2?240:105;return '<path d="M'+x+' 170 L'+labelX+' '+(i%2?labelY-14:labelY+9)+'" stroke="'+b.color+'" opacity=".55"/><circle cx="'+x+'" cy="170" r="'+(d.view==='true'?b.radius/max*535:4)+'" fill="'+b.color+'"/><circle cx="'+x+'" cy="170" r="5" fill="none" stroke="'+b.color+'" stroke-dasharray="2 3"/><text x="'+labelX+'" y="'+labelY+'" text-anchor="middle" style="font-size:10px">'+name(b)+'</text>';}).join('')+'<text x="40" y="293">'+L('Sol','Sun')+' · 0 '+L('UA','AU')+'</text><text x="585" y="293" text-anchor="end">'+fmt(max/AU,2)+' '+L('UA','AU')+' · '+(log?L('LOGARÍTMICO log(1 + UA)','LOGARITHMIC log(1 + AU)'):'LINEAR')+'</text>',L('Semieixos maiores numa régua comum; anéis pontilhados são localizadores','Semi-major axes on a common ruler; dotted rings are locators'));
  }
  return '<div class="tabs">'+[['sizes',L('Tamanhos relativos','Relative sizes')],['distances',L('Distâncias relativas','Relative distances')],['true',L('Escala real combinada','Combined true scale')]].map(([v,txt])=>B('scale-view',txt,{value:v,cls:d.view===v?'active':''})).join('')+'</div><div class="lab-layout"><div><div class="diagram"><div class="scale-viewport" tabindex="0" role="region" aria-label="'+L('Régua ampliável; role horizontalmente quando ampliada','Zoomable ruler; scroll horizontally when enlarged')+'" style="--scale-zoom:'+d.zoom+'">'+diagram+'</div></div>'+notice(d.view==='true'?L('Uma única escala para raios e distâncias. Discos subpixels são esperados; anéis pontilhados só localizam os centros.','One scale for radii and distances. Subpixel disks are expected; dotted rings only locate centers.'):L('O laboratório preserva a câmera e as medições da exploração. O zoom amplia a régua inteira sem alterar proporções.','The laboratory preserves the explorer camera and measurements. Zoom enlarges the entire ruler without changing proportions.'))+'</div><div class="stack">'+S('scale.group',L('Mundos na régua','Worlds on the ruler'),[['all',L('Oito planetas','Eight planets')],['inner',L('Planetas rochosos','Rocky planets')],['giants',L('Planetas gigantes','Giant planets')]],d.group)+R('scale.zoom',L('Ampliar régua','Enlarge ruler'),d.zoom,1,4,.25,'×')+S('scale.ref',L('E se este corpo tivesse…','What if this body were…'),optionBodies(name,[byId.sun,...planets,byId.moon]),d.ref)+N('scale.size',L('Diâmetro do objeto de referência','Reference object diameter'),d.size,.01,1000)+S('scale.unit',L('Unidade familiar','Familiar unit'),[['mm','mm'],['cm','cm'],['m','m']],d.unit)+(d.view==='sizes'?K('scale.includeSun',L('Incluir o Sol','Include the Sun'),d.includeSun):S('scale.axis',L('Eixo de distância','Distance axis'),[['linear',L('Linear','Linear')],['log',L('Logarítmico','Logarithmic')]],d.view==='true'?'linear':d.axis,d.view==='true'?'disabled':''))+B('lab-reset',L('Restaurar laboratório','Reset laboratory'),{ico:'reset',cls:'secondary'})+'</div></div><div class="table-wrap"><table><thead><tr><th>'+L('Corpo','Body')+'</th><th>'+L('Diâmetro no modelo (m)','Model diameter (m)')+'</th><th>'+L('Semieixo maior no modelo (m)','Model semi-major axis (m)')+'</th><th>'+L('Semieixo real (UA)','Real semi-major axis (AU)')+'</th></tr></thead><tbody>'+list.map(b=>'<tr><td>'+name(b)+'</td><td>'+fmt(b.radius*2*ratio,5)+'</td><td>'+(b.a?fmt(b.a*ratio,2):'—')+'</td><td>'+(b.a?fmt(b.a/AU,3):'—')+'</td></tr>').join('')+'</tbody></table></div><p class="metric-note">'+L('Diâmetros médios. Distâncias são semieixos maiores, não separações instantâneas.','Mean diameters. Distances are semi-major axes, not instantaneous separations.')+'</p>';
}

function renderMeasure({s,L,name,fmt}){const m=s.measurement||s.toolData.measure,time=m.frozen?m.time:s.clock.time,result=distanceAt(m.a,m.b,time),angle=angularSeparation(m.a,m.b,m.observer,time);return `<div class="form-grid">${S('measure.a',L('Primeiro extremo','First endpoint'),optionBodies(name),m.a)}${S('measure.b',L('Segundo extremo','Second endpoint'),optionBodies(name),m.b)}</div><div class="lab-readout">${readout(`<span data-live="distance-km">${fmt(result.km)}</span> km`,L('Centro a centro','Center to center'))}${readout(`<span data-live="distance-au">${fmt(result.au,6)}</span> ${L('UA','AU')}`,L('Distância física','Physical distance'))}${readout(`<span data-live="distance-light">${fmt(result.seconds,2)}</span> s`,L('Tempo de ida da luz','One-way light-time'))}</div><div class="diagram" style="margin-top:20px;min-height:130px">${svg(`<circle cx="70" cy="65" r="20" fill="${byId[m.a].color}"/><path d="M100 65h420" stroke="#d5b27b" stroke-dasharray="5 8"/><circle cx="550" cy="65" r="20" fill="${byId[m.b].color}"/><text x="70" y="110" text-anchor="middle">${name(byId[m.a])}</text><text x="550" y="110" text-anchor="middle">${name(byId[m.b])}</text><circle id="tool-light-pulse" cx="100" cy="65" r="4" fill="#fff6c1"/>`,L('Régua de distância; linha ilustrativa','Distance ruler; illustrative line'),'0 0 620 135')}</div><div class="row" style="margin-top:16px">${B('measure-swap',L('Trocar extremos','Swap endpoints'),{ico:'reverse',cls:'secondary'})}${B('measure-freeze',m.frozen?L('Retomar medida ao vivo','Resume live measurement'):L('Congelar nesta data','Freeze at this date'),{ico:m.frozen?'play':'pause',cls:'secondary',pressed:m.frozen})}${B('light-pulse',L('Enviar um pulso de luz','Send a light pulse'),{ico:'spark',cls:'primary'})}${B('measure-save',L('Guardar medição','Save measurement'),{ico:'save',cls:'secondary'})}${B('measure-scene',L('Escolher extremos na cena','Pick endpoints in scene'),{ico:'focus',cls:'secondary'})}</div>${notice(L('O pulso sempre percorre o desenho em 5 segundos reais. Essa animação é acelerada ou reduzida; usa extremos estáticos no instante escolhido. A medida numérica vem de coordenadas físicas e independe da escala visual.','The pulse always crosses the diagram in 5 real seconds. This animation is sped up or slowed down; endpoints are static at the chosen instant. The numeric measurement uses physical coordinates and is independent of display scale.'))}<div class="form-grid">${S('measure.observer',L('Observador da separação angular','Angular separation observer'),optionBodies(name),m.observer)}<div class="readout"><strong data-live="angle">${angle===null?L('Indefinida','Undefined'):fmt(angle,3)+'°'}</strong><small>${L('Ângulo geométrico; sem aberração ou correção de tempo da luz','Geometric angle; no aberration or light-time correction')}</small></div></div><p class="small">${m.frozen?L('Congelada em','Frozen at'):L('Data da medição','Measurement date')}: <time data-live="measure-date">${new Date(time).toISOString()}</time></p>${s.measureHistory.length?section(L('Histórico desta sessão','Session history'),`<div class="table-wrap"><table><thead><tr><th>UTC</th><th>${L('Extremos','Endpoints')}</th><th>km</th><th>s</th></tr></thead><tbody>${s.measureHistory.map(r=>`<tr><td>${new Date(r.time).toISOString().slice(0,19)}</td><td>${name(byId[r.a])} → ${name(byId[r.b])}</td><td>${fmt(r.km)}</td><td>${fmt(r.seconds,2)}</td></tr>`).join('')}</tbody></table></div>${B('export-measurements',L('Exportar histórico CSV','Export history CSV'),{ico:'download',cls:'secondary'})}`):''}`;}

function renderSeasons({s,L,fmt}){const d=s.toolData.seasons,r=daylight(d.tilt,d.latitude,d.phase),season=k=>L(...({summer:['Verão','Summer'],winter:['Inverno','Winter'],equinox:['Equinócio','Equinox']}[k]));const x=380,y=172,tilt=d.tilt*Math.sin(d.phase*RAD);return `<div class="lab-layout"><div><div class="diagram">${svg(`<defs><linearGradient id="season-light"><stop stop-color="#8eb5d5"/><stop offset=".49" stop-color="#5d82a5"/><stop offset=".51" stop-color="#172b40"/><stop offset="1" stop-color="#101c2a"/></linearGradient></defs><circle cx="48" cy="172" r="39" fill="#e9b867"/>${[110,148,186,224].map(yy=>`<path d="M100 ${yy}h140m-8-4 8 4-8 4" stroke="#c9a16e" opacity=".6" fill="none"/>`).join('')}<circle cx="${x}" cy="${y}" r="85" fill="url(#season-light)"/><g transform="translate(${x} ${y}) rotate(${-tilt})"><ellipse rx="85" ry="20" fill="none" stroke="#93c5d4"/><path d="M0 115V-115m-6 9 6-9 6 9" stroke="#eed1a3" stroke-width="2" fill="none"/><text x="9" y="-115">N</text><text x="9" y="122">S</text><ellipse cy="${-Math.sin(d.latitude*RAD)*85}" rx="${Math.abs(Math.cos(d.latitude*RAD))*85}" ry="10" fill="none" stroke="#e1c18d" stroke-dasharray="3 4"/></g><text x="305" y="325">${L('Equador e latitude escolhida','Equator and selected latitude')}</text>`,L('Modelo esquemático de inclinação e luz solar','Schematic model of tilt and sunlight'))}</div><div class="lab-readout">${readout(`${fmt(r.hours,2)} h`,L('Luz no horizonte ideal','Daylight at ideal horizon'))}${readout(season(r.north),L('Hemisfério norte','Northern hemisphere'))}${readout(season(r.south),L('Hemisfério sul','Southern hemisphere'))}</div><p class="metric-note">${L('Declinação solar','Solar declination')}: ${fmt(r.declination,2)}°. ${L('Sem refração atmosférica; Sol pontual. Dia polar = 24 h; noite polar = 0 h.','No atmospheric refraction; point-source Sun. Polar day = 24 h; polar night = 0 h.')}</p></div><div class="stack lab-controls">${notice(L('EXPERIMENTO HIPOTÉTICO · A Terra do explorador permanece inalterada.','HYPOTHETICAL EXPERIMENT · Explorer Earth remains unchanged.'),'caution')}${R('seasons.tilt',L('Inclinação axial','Axial tilt'),d.tilt,0,90,.1,'°')}${R('seasons.latitude',L('Latitude (sul − / norte +)','Latitude (south − / north +)'),d.latitude,-90,90,1,'°')}${R('seasons.phase',L('Posição na órbita','Orbital position'),d.phase,0,360,1,'°')}<div class="row">${B('season-preset',L('Equinócio','Equinox'),{value:'0',cls:'secondary'})}${B('season-preset',L('Solstício norte','Northern solstice'),{value:'90',cls:'secondary'})}${B('season-preset',L('Solstício sul','Southern solstice'),{value:'270',cls:'secondary'})}${B('lab-reset',L('Restaurar','Reset'),{ico:'reset',cls:'secondary'})}</div>${external('https://science.nasa.gov/learn/heat/resource/earths-spin-tilt-and-orbit/',L('Por que temos estações? · NASA','Why do we have seasons? · NASA'))}</div></div>`;}

function renderMoon({s,L,fmt}){const d=s.toolData.moon,p=lunarPhase(d.angle),phases=[['Nova','New'],['Crescente','Waxing crescent'],['Quarto crescente','First quarter'],['Gibosa crescente','Waxing gibbous'],['Cheia','Full'],['Gibosa minguante','Waning gibbous'],['Quarto minguante','Last quarter'],['Minguante','Waning crescent']];
  return `<div class="lab-layout"><div><div class="diagram">${lunarGeometry(d,L)}</div><div class="lab-readout">${readout(`${fmt(p.fraction*100,1)}%`,L('Fração da fase geométrica','Geometric phase fraction'))}${readout(`${fmt(apparentDiameter(byId.sun.radius,AU),3)}°`,L('Sol a 1 UA','Sun at 1 AU'))}${readout(`${fmt(apparentDiameter(byId.moon.radius,384400),3)}°`,L('Lua a 384.400 km','Moon at 384,400 km'))}</div>${notice(L('Fases não são a sombra da Terra. Eclipses exigem alinhamento de planos. Desenho esquemático, sem previsão de data ou local; os tamanhos aparentes usam as distâncias físicas indicadas.','Phases are not Earth’s shadow. Eclipses require orbital-plane alignment. Schematic drawing, without date or location predictions; apparent sizes use the stated physical distances.'))}</div><div class="stack lab-controls">${R('moon.angle',L('Alongamento da Lua','Lunar elongation'),d.angle,0,360,1,'°')}${K('moon.inclination',L('Plano inclinado em 5,16°','Plane tilted by 5.16°'),d.inclination)}${notice(d.inclination?L('Com inclinação, a Lua pode passar acima ou abaixo das sombras nas fases nova e cheia. As predefinições alinham um nó de forma esquemática.','With inclination, the Moon can pass above or below shadows at new and full Moon. Presets schematically align a node.'):L('Inclinação removida: hipótese que torna alinhamentos mensais possíveis.','Inclination removed: a hypothesis that makes monthly alignments possible.'),'caution')}<div class="row">${B('moon-preset',L('Lua nova','New Moon'),{value:'new',cls:'secondary'})}${B('moon-preset',L('Lua cheia','Full Moon'),{value:'full',cls:'secondary'})}${B('moon-preset',L('Eclipse solar · esquema','Solar eclipse · diagram'),{value:'solar',cls:'secondary'})}${B('moon-preset',L('Eclipse lunar · esquema','Lunar eclipse · diagram'),{value:'lunar',cls:'secondary'})}${B('moon-step',L('Próxima fase','Next phase'),{ico:'next',cls:'secondary'})}${B('lab-reset',L('Restaurar','Reset'),{ico:'reset',cls:'secondary'})}</div>${external('https://science.nasa.gov/moon/eclipses/',L('Eclipses explicados · NASA','Eclipses explained · NASA'))}</div></div>`;}

function renderKepler({s,L,fmt}){const d=s.toolData.kepler,r=orbitExperiment(d.mass,d.a,d.e,d.testMass),a=210,b=a*Math.sqrt(1-d.e*d.e),focus=310+a*d.e;const points=[];for(let i=0;i<=60;i++){const q=orbitPoint(a,d.e,0,0,0,i/60*TAU);points.push(`${focus+q[0]} ${175+q[1]*.53}`);}const sector=(from,to)=>{const pts=[];for(let i=0;i<=24;i++){const q=orbitPoint(a,d.e,0,0,0,from+(to-from)*i/24);pts.push(`${focus+q[0]},${175+q[1]*.53}`);}return `${focus},175 `+pts.join(' ');};return `<div class="lab-layout"><div><div class="diagram">${svg(`<path d="M${points.join(' L')}" fill="none" stroke="#7594a9"/><polygon points="${sector(0,.6)}" fill="#e0b66c2e" stroke="#d5b17966"/><polygon points="${sector(Math.PI,Math.PI+.6)}" fill="#8ebedc23" stroke="#86bbd866"/><circle cx="${focus}" cy="175" r="${12*Math.sqrt(d.mass)}" fill="#e9bc72"/><circle id="kepler-orbiter" cx="${focus+a*(1-d.e)}" cy="175" r="5" fill="#d3e4ed"/><text x="310" y="329" text-anchor="middle">${L('Áreas iguais em tempos iguais · plano comprimido verticalmente','Equal areas in equal times · vertically compressed plane')}</text>`,L('Órbita elíptica e duas áreas de tempo igual','Elliptic orbit and two equal-time areas'))}</div><div class="lab-readout">${readout(`${fmt(r.period/DAY,2)} d`,L('Período derivado','Derived period'))}${readout(`${fmt(r.perihelion,3)} ${L('UA','AU')}`,L('Periélio','Perihelion'))}${readout(`${fmt(r.aphelion,3)} ${L('UA','AU')}`,L('Afélio','Aphelion'))}</div><p class="metric-note">${L('Velocidade no periélio / afélio','Speed at perihelion / aphelion')}: ${fmt(r.vPeri,2)} / ${fmt(r.vApo,2)} km/s. ${L('O período de referência a 1 UA e 1 massa solar é','Baseline period at 1 AU and 1 solar mass is')} ${fmt(orbitExperiment(1,1,0).period/DAY,2)} d.</p><div class="row">${B('kepler-run',d.running?L('Pausar','Pause'):L('Executar','Run'),{ico:d.running?'pause':'play',cls:'primary'})}${B('kepler-predict',L('Fazer previsão','Make a prediction'),{cls:'secondary'})}${B('kepler-baseline',L('Comparar à referência','Compare to baseline'),{cls:'secondary'})}${B('save-experiment',L('Guardar experimento','Save experiment'),{ico:'save',cls:'secondary'})}${B('export-experiment',L('Exportar hipótese','Export hypothesis'),{ico:'download',cls:'secondary'})}</div>${d.prediction?notice(e(d.prediction)):''}</div><div class="stack lab-controls">${notice(L('HIPÓTESE · Dois corpos, massa de teste desprezível. A demonstração percorre uma órbita em 12 s reais. Nenhum parâmetro altera o Sistema Solar.','HYPOTHESIS · Two bodies, negligible test mass. The demonstration completes an orbit in 12 real seconds. No parameter changes the Solar System.'),'caution')}${R('kepler.mass',L('Massa central (massas solares)','Central mass (solar masses)'),d.mass,.1,5,.1)}${R('kepler.a',L('Semieixo maior (UA)','Semi-major axis (AU)'),d.a,.1,10,.1)}${R('kepler.e',L('Excentricidade (elipses limitadas)','Eccentricity (bound ellipses)'),d.e,0,.9,.01)}${N('kepler.testMass',L('Massa de teste (kg; não muda a órbita)','Test mass (kg; does not change orbit)'),d.testMass,1,10000)}<div class="row">${B('kepler-preset',L('Círculo','Circle'),{value:'circle',cls:'secondary'})}${B('kepler-preset',L('Elipse','Ellipse'),{value:'ellipse',cls:'secondary'})}${B('kepler-preset',L('Dobrar a órbita','Double orbit size'),{value:'double',cls:'secondary'})}${B('lab-reset',L('Restaurar','Reset'),{ico:'reset',cls:'secondary'})}</div><p class="metric-note">T = 2π√(a³/GM). ${L('Entradas convertidas para SI. Sem órbitas parabólicas, hiperbólicas ou perturbações.','Inputs converted to SI. No parabolic or hyperbolic orbits, or perturbations.')}</p></div></div>`;}

function renderTime({s,L,name,fmt}){const c=s.clock,d=s.toolData;return `<div class="lab-layout"><div class="stack">${notice(L('UTC · 01/01/1800 a 01/01/2050. Ao atingir o limite, a reprodução pausa. Posições aproximadas; UTC tratado como TDB para fins educativos.','UTC · January 1, 1800 to January 1, 2050. Playback pauses at the boundary. Approximate positions; UTC treated as TDB for education.'))}<label class="field">${L('Data e hora UTC','UTC date and time')}<input type="datetime-local" data-field="dateInput" value="${d.dateInput||new Date(c.time).toISOString().slice(0,16)}" min="1800-01-01T00:00" max="2050-01-01T00:00"/></label><div class="row">${B('apply-date',L('Ir para esta data','Go to this date'),{ico:'calendar',cls:'primary'})}${B('now',L('Agora','Now'),{cls:'secondary'})}${B('reset-simulation',L('Restaurar simulação','Reset simulation'),{ico:'reset',cls:'secondary'})}</div>${S('timelineSpan',L('Intervalo da linha do tempo','Timeline span'),[[30,L('30 dias','30 days')],[365,L('1 ano','1 year')],[3652.5,L('10 anos','10 years')],[36525,L('100 anos','100 years')]],d.timelineSpan)}${R('timeline',L('Deslocamento em dias a partir da data de referência','Days from reference date'),d.timelineOffset,-d.timelineSpan/2,d.timelineSpan/2,.1,' d')}<div class="linear-ruler"><span>${new Date(clamp(d.timelineAnchor-d.timelineSpan/2*DAY*1000,MIN_DATE,MAX_DATE)).toISOString().slice(0,10)}</span><span>UTC</span><span>${new Date(clamp(d.timelineAnchor+d.timelineSpan/2*DAY*1000,MIN_DATE,MAX_DATE)).toISOString().slice(0,10)}</span></div><p class="metric-note">${L('Mover a linha do tempo pausa a simulação. Intervalos são durações fixas, não meses de calendário.','Scrubbing pauses the simulation. Spans are fixed durations, not calendar months.')}</p></div><div class="stack">${N('customRate',L('Taxa com sinal (− inverte; 0 pausa)','Signed rate (− reverses; 0 pauses)'),d.customRate,-31557600,31557600)}${B('apply-rate',L('Aplicar velocidade','Apply rate'),{cls:'primary'})}<div class="row">${[1,10,100,1000,3600,DAY,7*DAY,30*DAY].map(v=>B('speed-preset',`${fmt(v)}×`,{value:String(v),cls:'secondary'})).join('')}</div>${S('stepSize',L('Tamanho do passo','Step size'),[[60,L('Um minuto','One minute')],[3600,L('Uma hora','One hour')],[DAY,L('Um dia','One day')],[7*DAY,L('Uma semana','One week')],...(byId[s.selected].period?[[byId[s.selected].period*DAY,L('Uma órbita do alvo','One target orbit')]]:[]),...(byId[s.selected].rotation?[[Math.abs(byId[s.selected].rotation)*DAY,L('Uma rotação do alvo','One target rotation')]]:[])],d.stepSize)}<div class="row">${B('step-custom',L('Passo anterior','Step backward'),{value:'-1',ico:'back',cls:'secondary'})}${B('step-custom',L('Próximo passo','Step forward'),{value:'1',ico:'next',cls:'secondary'})}${B('observe-orbit',L('Observar uma órbita','Observe one orbit'),{ico:'orbit',cls:'secondary',disabled:!byId[s.selected].period})}</div>${notice(L('1× = 1 segundo simulado por segundo real. Dia = 86.400 s; semana = 7 dias; mês demonstrativo = 30 dias. A aba oculta suspende o relógio sem acumular atraso.','1× = 1 simulated second per real second. Day = 86,400 s; week = 7 days; demonstration month = 30 days. A hidden tab suspends the clock without accumulating a gap.'))}</div></div>${section(L('Datas que vale revisitar','Dates worth revisiting'),`<div class="row">${B('save-bookmark',L('Guardar esta data','Save this date'),{ico:'save',cls:'primary'})}${B('bookmark-prev',L('Data salva anterior','Previous saved date'),{ico:'back',cls:'secondary'})}${B('bookmark-next',L('Próxima data salva','Next saved date'),{ico:'next',cls:'secondary'})}${B('open',L('Ver marcos históricos','View historical milestones'),{value:'missions',ico:'spark',cls:'secondary'})}${B('open',L('Demonstrações de alinhamento','Alignment demonstrations'),{value:'moon',ico:'moon',cls:'secondary'})}</div>`)}<div id="tool-error" role="alert"></div>`;}

function renderSettings({s,L}){const p=s.prefs;return `<div class="tabs">${[['cinema',L('Cinema','Cinematic')],['classroom',L('Sala de aula','Classroom')],['study',L('Estudo detalhado','Detailed study')],['low',L('Baixo consumo','Low power')]].map(([v,txt])=>B('preset',txt,{value:v,cls:'secondary'})).join('')}</div><div class="lab-layout"><div>${section(L('Apresentação','Presentation'),`<div class="form-grid">${S('pref.language',L('Idioma','Language'),[['pt','Português (Brasil)'],['en','English']],p.language)}${S('pref.presentation',L('Aparência','Appearance'),[['natural',L('Natural','Natural')],['enhanced',L('Realçada','Enhanced')]],p.presentation)}${S('pref.quality',L('Qualidade','Quality'),[['auto',L('Automática','Automatic')],['low',L('Baixa','Low')],['medium',L('Média','Medium')],['high',L('Alta','High')]],p.quality)}${S('pref.scale',L('Escala da cena','Scene scale'),[['explore',L('Exploração','Exploration')],['relative',L('Escala relativa real','True relative scale')]],p.scale)}${S('pref.units',L('Distâncias no inspetor','Inspector distances'),[['km',L('Quilômetros','Kilometers')],['mi',L('Milhas','Miles')]],p.units)}${S('pref.dateFormat',L('Formato de data','Date format'),[['locale',L('Localizado','Localized')],['iso','ISO 8601']],p.dateFormat)}</div>${notice(L('Natural usa iluminação auxiliar discreta e cores menos saturadas. Realçada favorece visibilidade. Nenhuma reproduz toda a percepção humana ou um instrumento específico.','Natural uses restrained fill light and less saturated color. Enhanced favors visibility. Neither reproduces all human perception or a specific instrument.'))}`)}${section(L('Camadas e orientação','Layers and orientation'),`<div class="form-grid">${S('pref.labels',L('Rótulos','Labels'),[['major',L('Objetos principais','Major objects')],['system',L('Sistema selecionado','Selected system')],['selected',L('Apenas seleção','Selection only')],['favorites',L('Favoritos','Favorites')],['none',L('Nenhum','None')]],p.labels)}${S('pref.orbits',L('Órbitas','Orbits'),[['all',L('Todas relevantes','All relevant')],['selected',L('Selecionada','Selected')],['system',L('Sistema selecionado','Selected system')],['none',L('Nenhuma','None')]],p.orbits)}</div>${K('pref.grid',L('Grade da eclíptica','Ecliptic grid'),p.grid)}${K('pref.axes',L('Eixo de rotação do alvo','Target rotation axis'),p.axes)}${K('pref.nodes',L('Periélio e afélio do alvo','Target perihelion and aphelion'),p.nodes)}${K('pref.velocity',L('Direção da velocidade (seta de comprimento ilustrativo)','Velocity direction (illustrative arrow length)'),p.velocity)}${K('pref.belt',L('Cinturão principal representativo','Representative main belt'),p.belt)}${K('pref.kuiper',L('Cinturão de Kuiper representativo','Representative Kuiper Belt'),p.kuiper)}${K('pref.smallBodies',L('Planetas anões, Vesta e cometa','Dwarf planets, Vesta and comet'),p.smallBodies)}${K('pref.trails',L('Trajetória passada do alvo','Target past trajectory'),p.trails)}${R('pref.trailDays',L('Duração da trajetória (dias)','Trail duration (days)'),p.trailDays,1,3650,1)}${B('clear-trails',L('Limpar trajetória','Clear trail'),{cls:'secondary'})}`)}</div><div>${section(L('Conforto de leitura','Reading comfort'),`<div class="stack">${S('pref.reducedMotion',L('Reduzir movimento','Reduce motion'),[['system',L('Preferência do sistema','System preference')],['on',L('Sempre','Always')],['off',L('Não','No')]],p.reducedMotion)}${R('pref.fontSize',L('Tamanho da interface','Interface size'),p.fontSize,1,1.3,.05,'×')}${R('pref.panelOpacity',L('Opacidade dos painéis','Panel opacity'),p.panelOpacity,.65,1,.05)}${R('pref.background',L('Intensidade das estrelas','Star intensity'),p.background,0,1,.05)}${R('pref.exposure',L('Exposição','Exposure'),p.exposure,.3,2,.05)}${R('pref.labelDensity',L('Densidade dos rótulos','Label density'),p.labelDensity,.5,1.5,.1)}${K('pref.highContrast',L('Rótulos de alto contraste','High-contrast labels'),p.highContrast)}${B('clean-background',L('Fundo limpo para projeção','Clean projection background'),{cls:'secondary'})}</div>`)}${section(L('Som e recursos opcionais','Sound and optional capabilities'),`${K('pref.sound',L('Permitir narração ao ativá-la no passeio','Allow narration when activated in a tour'),p.sound)}<p class="small">${L('Sem áudio automático. Os passeios possuem texto completo. Narração usa vozes disponíveis no navegador, após sua ação explícita. Gravação e tela cheia dependem do navegador. Instalação offline não faz parte desta prévia; a cena carregada não usa APIs remotas.','No automatic audio. Tours have complete text. Narration uses browser voices after your explicit action. Recording and fullscreen depend on the browser. Offline installation is not included in this preview; the loaded scene uses no remote APIs.')}</p><div class="row">${B('mute',L('Silenciar','Mute'),{ico:'mute',cls:'secondary'})}${B('fullscreen',L('Tela cheia','Fullscreen'),{ico:'focus',cls:'secondary'})}</div>`)}${section(L('Controle local','Local control'),`<div class="row">${B('reset-settings',L('Restaurar preferências visuais','Reset visual preferences'),{ico:'reset',cls:'secondary'})}${B('open',L('Dados, exportação e notas','Data, export and notes'),{value:'collections',ico:'book',cls:'secondary'})}${B('article',L('Sobre este modelo','About this model'),{value:'model',cls:'secondary'})}</div>${s.sceneDiagnostics.failedAssets?.length?B('retry-assets',L('Tentar carregar texturas novamente','Retry loading textures'),{ico:'reset',cls:'secondary'}):''}<details style="margin-top:20px"><summary>${L('Diagnóstico desta sessão','Session diagnostics')}</summary><pre id="diagnostics" style="font-size:11px;white-space:pre-wrap">${e(JSON.stringify(s.sceneDiagnostics||{},null,2))}</pre></details>`)} </div></div>`;}

function renderCollections({s,L,name}){const d=s.toolData,tab=d.collectionTab,labels={favorites:['Favoritos','Favorites'],viewpoints:['Vistas','Views'],bookmarks:['Datas','Dates'],notes:['Anotações','Notes'],experiments:['Experimentos','Experiments']};const items=tab==='favorites'?s.data.favorites.map(id=>({id,title:name(byId[id]),body:id})):s.data[tab];const filtered=items.filter(x=>x.title.toLowerCase().includes((d.collectionQuery||'').toLowerCase()));return `<p>${L('Seu espaço de observação. Tudo permanece neste navegador, sem conta ou envio para a nuvem.','Your observation space. Everything stays in this browser, without an account or cloud upload.')}</p><div class="tabs collection-tabs">${Object.entries(labels).map(([id,label])=>B('collection-tab',`${L(...label)} <span class="muted">${s.data[id].length}</span>`,{value:id,cls:tab===id?'active':''})).join('')}</div><input class="search-wide" type="search" data-field="collectionQuery" aria-label="${L('Buscar nas coleções','Search collections')}" placeholder="${L('Buscar suas observações…','Search your observations…')}" value="${e(d.collectionQuery||'')}"/>${tab==='notes'?`<div class="stack"><label class="field">${L('Título da anotação','Note title')}<input data-field="noteTitle" maxlength="100" value="${e(d.noteTitle)}"/></label><label class="field">${L('O que você observou?','What did you observe?')}<textarea data-field="noteText" maxlength="4000" placeholder="${L('Uma pergunta, um detalhe, uma descoberta…','A question, a detail, a discovery…')}">${e(d.noteText)}</textarea></label><div class="row">${B('save-note',d.editNote?L('Salvar edição','Save edit'):L('Guardar anotação','Save note'),{ico:'save',cls:'primary'})}<span class="small muted">${name(byId[s.selected])} · UTC</span>${d.editNote?B('cancel-note-edit',L('Cancelar edição','Cancel edit'),{cls:'secondary'}):''}</div></div>`:tab==='viewpoints'?`<div class="form-grid"><label class="field">${L('Nome da vista','View title')}<input data-field="viewTitle" maxlength="100" value="${e(d.viewTitle)}"/></label>${S('viewDateMode',L('Ao reabrir','When reopening'),[['saved',L('Restaurar a data salva','Restore saved date')],['current',L('Usar a data atual da simulação','Use current simulation date')]],d.viewDateMode)}</div>${B('save-viewpoint',L('Guardar vista atual','Save current view'),{ico:'save',cls:'primary'})}`:tab==='bookmarks'?B('save-bookmark',L('Guardar data atual','Save current date'),{ico:'calendar',cls:'primary'}):''}<div style="margin-top:20px">${filtered.map(x=>`<div class="list-card"><i class="body-dot" style="--body-color:${byId[x.body].color}"></i><div class="content"><h3>${e(x.title)}</h3>${x.time?`<p class="small">${name(byId[x.body])} · ${new Date(x.time).toISOString().slice(0,16)} UTC</p>`:''}${x.text?`<p style="white-space:pre-wrap">${e(x.text)}</p>`:''}<div class="row">${B('collection-open',L('Revisitar','Revisit'),{value:x.id,ico:'focus',cls:'secondary'})}${tab!=='favorites'?B('collection-rename',L('Renomear','Rename'),{value:x.id,cls:'secondary'}):''}${tab==='notes'?B('note-edit',L('Editar texto','Edit text'),{value:x.id,cls:'secondary'}):''}${tab!=='favorites'?B('collection-duplicate',L('Duplicar','Duplicate'),{value:x.id,cls:'secondary'}):''}${B('collection-delete',L('Excluir','Delete'),{value:x.id,cls:'danger'})}</div></div></div>`).join('')||`<div class="empty">${L('Ainda não há observações aqui. Cada viagem pode ser o começo de uma.','No observations here yet. Every journey can be the start of one.')}</div>`}</div>${section(L('Seus dados viajam com você','Your data travels with you'),`<div class="row">${B('export-data',L('Exportar coleções e preferências','Export collections and preferences'),{ico:'download',cls:'secondary'})}${B('clear-collection',L('Limpar esta coleção','Clear this collection'),{cls:'danger'})}</div><label class="field" style="margin-top:15px">${L('Importar arquivo JSON (até 2 MB)','Import JSON file (up to 2 MB)')}<input type="file" data-field="importFile" accept="application/json,.json"/></label><p class="metric-note">${L('A importação mostra uma revisão antes de mesclar. Fotos não são incorporadas ao JSON. Seu texto não é incluído ao compartilhar apenas uma vista.','Import shows a review before merging. Photos are not embedded in JSON. Your notes are excluded when sharing only a view.')}</p>`)}`;}

function renderMissions({s,L,name}){const d=s.toolData;const list=missions.filter(m=>(d.missionBody==='all'||m.body===d.missionBody)&&(d.missionEra==='all'||(d.missionEra==='early'?Number(m.launch.slice(0,4))<2000:Number(m.launch.slice(0,4))>=2000))&&(d.missionType==='all'||m.type[1]===d.missionType));return `<p>${L('Marcos históricos com fontes. As rotas são conexões de destinos, não trajetórias de voo ou rastreamento ao vivo.','Sourced historical milestones. Routes connect destinations; they are not flight trajectories or live tracking.')}</p><div class="form-grid">${S('missionBody',L('Destino','Destination'),[['all',L('Todos os destinos','All destinations')],...optionBodies(name,[...new Set(missions.map(m=>m.body))].map(id=>byId[id]))],d.missionBody)}${S('missionEra',L('Época','Era'),[['all',L('Todas as épocas','All eras')],['early',L('Antes de 2000','Before 2000')],['recent',L('Desde 2000','Since 2000')]],d.missionEra)}${S('missionType',L('Tipo de missão','Mission type'),[['all',L('Todos','All')],...[...new Set(missions.map(m=>m.type[1]))].map(type=>[type,L(...missions.find(m=>m.type[1]===type).type)])],d.missionType)}</div><div style="margin-top:25px">${list.map(m=>`<div class="list-card"><div class="mission-date">${m.event}</div><div class="content mission-line"><h3>${m.name}</h3><p class="small muted">${m.agency} · ${L(...m.type)} · ${name(byId[m.body])}</p><p>${L(...m.text)}</p><p class="metric-note">${L('Lançamento','Launch')}: ${m.launch} · ${L(...m.eventType)}: ${m.event}${m.end?` · ${L('Fim da missão','Mission end')}: ${m.end}`:''}</p><div class="row">${B('mission-visit',L('Visitar o marco','Visit milestone'),{value:m.id,ico:'calendar',cls:'secondary'})}${external(m.source,L('Fonte institucional','Institutional source'))}</div></div></div>`).join('')||notice(L('Nenhuma missão nesta combinação de filtros.','No missions match this combination of filters.'))}</div><p class="metric-note">${L('Fontes consultadas em','Sources accessed on')} ${DATA_DATE}. ${L('Campos vazios de término não afirmam estado ativo.','Empty end-date fields do not assert active status.')}</p>`;}

function renderOuter({s,L,fmt}){const d=s.toolData.outer,stages=[{title:L('A região dos planetas','The planetary region'),a:30,text:L('Netuno marca o limite da família de oito planetas, não o fim do Sistema Solar.','Neptune marks the extent of the eight-planet family, not the end of the Solar System.')},{title:L('O cinturão de Kuiper','The Kuiper Belt'),a:50,text:L('Uma população gelada além de Netuno. Aqui, 30–50 UA é uma região de contexto, não uma parede.','An icy population beyond Neptune. Here, 30–50 AU is a contextual region, not a wall.')},{title:L('A vizinhança heliosférica','The heliospheric neighborhood'),a:120,text:L('A heliopausa é uma fronteira do plasma solar, variável com direção e tempo. O marco de 120 UA é esquemático.','The heliopause is a solar-plasma boundary that varies with direction and time. The 120 AU marker is schematic.')},{title:L('Uma nuvem proposta','A proposed cloud'),a:2000,text:L('A Nuvem de Oort é uma região teórica muito distante. Não temos um mapa de objetos individuais nela.','The Oort Cloud is a very distant theoretical region. We do not have a map of its individual objects.')},{title:L('Uma vizinhança imensa','An immense neighborhood'),a:100000,text:L('Até cerca de 100 mil UA na representação conceitual da Nuvem de Oort. Não existe uma única esfera que defina todas as bordas do Sistema Solar.','Up to roughly 100,000 AU in the conceptual Oort Cloud representation. No single sphere defines every Solar System boundary.')}],stage=stages[d.step];const base=d.origin==='earth'?1:0;return `<div class="eyebrow">${L('JORNADA DE DISTÂNCIA','DISTANCE JOURNEY')} · ${d.step+1} / ${stages.length}</div><h2 style="margin:15px 0">${stage.title}</h2><p>${stage.text}</p><div class="diagram">${svg(`<defs><radialGradient id="outer-glow"><stop stop-color="#799cb531"/><stop offset="1" stop-color="#799cb502"/></radialGradient></defs><circle cx="310" cy="163" r="139" fill="url(#outer-glow)" stroke="#7893a160" stroke-dasharray="2 5"/>${[26,51,82,110].map(r=>`<ellipse cx="310" cy="163" rx="${r}" ry="${r*.4}" fill="none" stroke="#88a8ba25"/>`).join('')}<circle cx="310" cy="163" r="5" fill="#f1c184"/><path d="M310 163h140" stroke="#a6c5d3"/><text x="380" y="150" text-anchor="middle">${fmt(stage.a)} ${L('UA','AU')}</text><text x="310" y="328" text-anchor="middle">${L('CONTEXTO ESQUEMÁTICO · RÉGUA MUDA EM CADA ETAPA','SCHEMATIC CONTEXT · RULER CHANGES AT EVERY STEP')}</text>`,L('Região externa esquemática com régua de distância','Schematic outer region with a distance ruler'))}</div><div class="lab-readout">${readout(`${fmt(stage.a-base)} ${L('UA','AU')}`,L('Distância de referência','Reference distance'))}${readout(`${fmt((stage.a-base)*AU/C/DAY,2)} d`,L('Tempo de ida da luz','One-way light-time'))}${readout(`${fmt(stage.a/30,1)}×`,L('Semieixo de Netuno (aprox.)','Neptune semi-major axis (approx.)'))}</div><div class="row" style="margin-top:20px">${B('outer-step',L('Anterior','Previous'),{value:'-1',ico:'back',cls:'secondary',disabled:d.step===0})}${B('outer-step',L('Mais longe','Farther out'),{value:'1',ico:'next',cls:'primary',disabled:d.step===4})}${B('close-tool',L('Voltar aos planetas','Return to the planets'),{ico:'reset',cls:'secondary'})}${S('outer.origin',L('Origem da régua','Ruler origin'),[['sun',L('Sol','Sun')],['earth',L('Terra a 1 UA no mesmo raio (esquema)','Earth at 1 AU on the same ray (diagram)')]],d.origin)}</div><div class="source-list" style="margin-top:20px">${regions.slice(1).map(r=>external(r.source,L(...r.name)+' · NASA')).join('')}${external('https://science.nasa.gov/mission/voyager/',L('A heliosfera · NASA Voyager','The heliosphere · NASA Voyager'))}</div>`;}

function renderFrames({s,L,name}){const d=s.toolData,origin=d.frameBody==='selected'?s.selected:d.frameBody,physical=positionsAt(s.clock.time).positions,base=physical[origin]||physical.sun;const scale=v=>{const r=length(v)/AU;return r?Math.log1p(r)/Math.log(32)*133/r:0;};const project=v=>[310+v[0]/AU*scale(v),166-v[1]/AU*scale(v)];let trace='';for(let i=0;i<=140;i++){const time=clamp(s.clock.time+(i-70)*DAY*1000*5,MIN_DATE,MAX_DATE),p=positionsAt(time).positions,v=sub(p.mars,p[origin]||p.sun),[x,y]=project(v);trace+=`${i?'L':'M'}${x},${y} `;}return `<p>${L('A configuração física permanece a mesma. Apenas subtraímos a posição do observador e projetamos os vetores no plano da eclíptica.','The physical configuration stays unchanged. We only subtract the observer position and project vectors onto the ecliptic plane.')}</p><div class="form-grid">${S('frameBody',L('Referencial do diagrama','Diagram reference frame'),[['sun',L('Sol','Sun')],['earth',L('Terra','Earth')],['selected',L('Objeto selecionado','Selected object')]],d.frameBody)}${B('apply-frame',L('Usar este referencial no mapa','Use this reference in the map'),{ico:'compass',cls:'primary'})}</div><div class="diagram" style="margin-top:20px">${svg(`<path d="${trace}" fill="none" stroke="#d395755f"/><path d="M310 16v305M160 166h300" stroke="#68819a28"/>`+[byId.sun,...planets].map(b=>{const[x,y]=project(sub(physical[b.id],base));return `<circle cx="${x}" cy="${y}" r="${b.id===origin?5:3}" fill="${b.color}"/><text x="${x+8}" y="${y-8}" style="font-size:11px">${name(b)}</text>`;}).join('')+`<text x="20" y="330">${L('Traço de Marte: ±350 dias · raios logarítmicos','Mars trace: ±350 days · logarithmic radii')}</text>`,L('Movimento aparente geométrico','Geometric apparent motion'))}</div>${notice(L('O laço geocêntrico é um efeito de perspectiva orbital. Não inclui tempo da luz, aberração, observador na superfície nem catálogo real de estrelas. Seguir com a câmera é uma operação separada.','The geocentric loop is an orbital-perspective effect. It omits light-time, aberration, a surface observer and real star catalogs. Camera following is a separate operation.'))}`;}
